begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(4);
insert into auth.users(id,email) values('15000000-0000-4000-8000-000000000004','wp15-bound@example.invalid');
create temporary table wp15_bound(id uuid,version text,events bigint);
grant select,insert,update on wp15_bound to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"15000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
insert into wp15_bound select public.create_wedding('WP15 bound synthetic','Test city'),null,null;
select public.save_draft_setup((select id from wp15_bound),(select state_version from public.weddings),'WP15 bound synthetic','Test city',null,true,null,'[{"title":"Reception","guest_count":250}]');
select public.generate_draft((select id from wp15_bound),(select state_version from public.weddings));
select public.activate_plan((select id from wp15_bound),(select state_version from public.weddings),true);
update wp15_bound set version=(select state_version from public.weddings),events=(select count(*) from public.audit_events);
select throws_ok($$select public.finance_cost((select id from wp15_bound),null,(select state_version from public.weddings),'create',jsonb_build_object('title','Unsafe calculated forecast','ceremony_id',(select id::text from public.ceremonies),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise','100000000000'),false,null)$$,'22023',null,'derived forecast above agreed item cap rejected before persistence');
select is((select count(*) from public.cost_items),0::bigint,'unsafe row not retained');
select ok((select state_version from public.weddings)=(select version from wp15_bound) and (select count(*) from public.audit_events)=(select events from wp15_bound),'unsafe forecast rolls back version and audit');
select lives_ok($$select public.finance_cost((select id from wp15_bound),null,(select state_version from public.weddings),'create',jsonb_build_object('title','Exact boundary','ceremony_id',(select id::text from public.ceremonies),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise','400000000'),false,null)$$,'exact per-item product boundary accepted');
select * from finish();
rollback;
